import sys, json, glob, collections
sys.path.insert(0,'/workspace')
import pyarrow.parquet as pq
from verl.utils.reward_score import taco

tr = pq.read_table('/workspace/taco_verl/train.parquet').to_pylist()
raw = []
for f in sorted(glob.glob('/autorlbench/datasets/BAAI__TACO/ALL/*.parquet')):
    raw += pq.read_table(f).to_pylist()

def q_of(r):
    c = r['prompt'][0]['content']
    return c.split('QUESTION:\n',1)[1].rsplit('\nANSWER:\n',1)[0].rstrip()
def strip_suf(q):
    q=q.rstrip(); s=' \\nUse Standard Input format'
    return q[:-len(s)].rstrip() if q.endswith(s) else q
def nk(q): return ' '.join(q.split())
idx = collections.defaultdict(list)
for r in raw: idx[nk(r['question'])].append(r)

# membership in cyh source
src = pq.read_table('/autorlbench/datasets/cyh2004__autorlbench-taco-verl-easy/train.parquet').to_pylist()
def sig(r):
    return (r['prompt'][0]['content'], r['reward_model']['ground_truth'])
srcset = set(sig(r) for r in src)

def work(i):
    r = tr[i]
    pid = r['extra_info']['problem_id']
    in_src = sig(r) in srcset
    q = strip_suf(q_of(r))
    cands = idx.get(nk(q), [])
    if not cands:
        return {'i': i, 'pid': pid, 'src': in_src, 'err': 'no_raw'}
    sols = []
    try:
        sols = json.loads(cands[0]['solutions'])
    except Exception:
        pass
    if not sols:
        return {'i': i, 'pid': pid, 'src': in_src, 'err': 'no_sol'}
    # spread picks, prefer code with input(
    order = list(range(len(sols)))
    prefer = [j for j in order if 'input(' in sols[j]]
    pick = (prefer or order)[:3]
    rates = []
    for j in pick:
        try:
            res = taco.compute_score(solution_str=sols[j], ground_truth=r['reward_model']['ground_truth'], extra_info=r['extra_info'])
            rates.append(res['pass_rate'])
        except Exception as e:
            rates.append(-2.0)
    return {'i': i, 'pid': pid, 'src': in_src, 'n_tests': r['extra_info']['n_tests'],
            'nsol': len(sols), 'rates': rates, 'best': max(rates) if rates else -1}

if __name__ == '__main__':
    import multiprocessing as mp
    n = len(tr)
    with mp.Pool(48) as pool:
        out = []
        for k, res in enumerate(pool.imap_unordered(work, range(n), chunksize=1)):
            out.append(res)
            if k % 100 == 0:
                print('done', k, flush=True)
    json.dump(out, open('/tmp/chk2/official_out.json','w'))
    print('TOTAL', len(out))
