    outpath='/tmp/chk2/official2.jsonl'
    done=set()
    if os.path.exists(outpath):
        for l in open(outpath):
            try: done.add(json.loads(l)['i'])
            except Exception: pass
    todo=[i for i in range(len(tr)) if i not in done]
    print('todo',len(todo),flush=True)
    with open(outpath,'a') as f, cf.ProcessPoolExecutor(max_workers=96) as ex:
