te=pq.read_table('/workspace/taco_verl/test.parquet').to_pylist()
V=json.load(open('/autorlbench/datasets/likaixin__TACO-verified/taco_verified.json'))
print('verified entries', len(V), flush=True)
def nk(q): return ' '.join(q.split())
vidx=collections.defaultdict(list)
for r in V: vidx[nk(r['question'])].append(r)
print('distinct q', len(vidx), flush=True)
def q_of(r):
    c=r['prompt'][0]['content']
    return c.split('QUESTION:\n',1)[1].rsplit('\nANSWER:\n',1)[0].rstrip()
def strip_suf(q):
    q=q.rstrip(); s=' \\nUse Standard Input format'
    return q[:-len(s)].rstrip() if q.endswith(s) else q
def key(r):
    g=json.loads(r['reward_model']['ground_truth'])
    return (tuple(g.get('inputs') or []), tuple(g.get('outputs') or []))
def vkey(v):
    try: g=json.loads(v['input_output'])
    except Exception: return None
    return (tuple(g.get('inputs') or []), tuple(g.get('outputs') or []))
stats=collections.Counter(); rows=[]
for split,rs in [('train',tr),('test',te)]:
    for r in rs:
        q=nk(strip_suf(q_of(r)))
        cands=vidx.get(q,[])
        if not cands: stats[split,'no_question']+=1; rows.append((split,r['extra_info']['problem_id'],'noq')); continue
        k=key(r)
        ks=[vkey(v) for v in cands]
        if any(x==k for x in ks): stats[split,'tests_match_verified']+=1
        elif all(x is None for x in ks): stats[split,'verified_unparseable']+=1
        else:
            stats[split,'tests_differ']+=1
            rows.append((split, r['extra_info']['problem_id'], 'diff', len(cands), len(k[0])))
print(dict(stats), flush=True)
json.dump(rows, open('/tmp/chk2/verified_mismatch.json','w'))
