import sys; sys.path.insert(0,'/workspace')
import pyarrow.parquet as pq, glob, json, collections, random, numpy as np
new=pq.read_table('/workspace/taco_verl/train.parquet').to_pylist()
old=pq.read_table('/tmp/chk2/train_original.parquet').to_pylist()
ver={x['pid']:x['status'] for x in json.load(open('/tmp/chk2/verified2.json')) if x['split']=='train'}
# difficulty composition of kept
raw=[]
for f in sorted(glob.glob('/autorlbench/datasets/BAAI__TACO/ALL/*.parquet')):
    raw+=pq.read_table(f, columns=['question','difficulty']).to_pylist()
def nk(q): return ' '.join(q.split())
didx={}
for r in raw: didx.setdefault(nk(r['question']), r['difficulty'])
def q_of(r):
    c=r['prompt'][0]['content']
    return c.split('QUESTION:\n',1)[1].rsplit('\nANSWER:\n',1)[0].rstrip()
def strip_suf(q):
    q=q.rstrip(); s=' \\nUse Standard Input format'
    return q[:-len(s)].rstrip() if q.endswith(s) else q
uniq={r['extra_info']['problem_id']:r for r in new}
print('kept difficulty', collections.Counter(didx.get(nk(strip_suf(q_of(r))),'?') for r in uniq.values()))
nt=np.array([r['extra_info']['n_tests'] for r in uniq.values()])
print('kept n_tests pct', np.percentile(nt,[0,25,50,75,90,100]).round(0))
# verify: all kept rows have status match
print('statuses', collections.Counter(ver.get(r['extra_info']['problem_id'],'?') for r in uniq.values()))
# duplicate rows are exact copies
cnt=collections.Counter(r['extra_info']['index'] for r in new)
print('index multiplicities', collections.Counter(cnt.values()))
EOF

